mapper.select:
SELECT ar.id, ar.rule_code AS ruleCode, ar.rule_name AS ruleName, ar.trigger_type AS triggerType, ar.trigger_condition AS triggerCondition, ar.action_device_id AS actionDeviceId, ar.action_command AS actionCommand, ar.action_parameter AS actionParameter, ar.enable_status AS enableStatus, CASE ar.enable_status WHEN 1 THEN '启用' ELSE '禁用' END AS enableStatusText, ar.create_by AS createBy, ar.create_time AS createTime FROM agri_iot_automation_rule ar WHERE ar.del_flag = 0
AND ar.rule_code LIKE CONCAT('%', #{dto.ruleCode}, '%')
AND ar.rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')
AND ar.enable_status = #{dto.enableStatus}
ORDER BY ar.create_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}
